(window.LP_CLIPS=window.LP_CLIPS||{});window.LP_CLIPS["pt"]=Object.assign(window.LP_CLIPS["pt"]||{},{"pip e a travessia segura": "", "pip, o guaxinim, acordou numa cidadezinha, e a manhã estava clara.": "", "pip queria ver o cachorro, que esperava do outro lado da rua.": "", "mas a rua era barulhenta, os carros eram rápidos, e pip, o gato e o pato eram pequenos demais para atravessar.": "", "pip sentou e pensou. as pessoas construíram esta rua, então as pessoas podem mudá-la.": "", "então pip bateu nas portas, e os vizinhos saíram para ouvir.": "", "juntos, pediram um lugar seguro para atravessar, e a cidade disse sim.": "", "vieram as escavadeiras, o rolo passou, e os operários pintaram faixas brilhantes.": "", "agora os carros param, e todos atravessam juntos.": "", "pip abraçou o cachorro. uma voz pequena e alguns bons amigos tinham mudado a rua.": "", "o mundo é feito pelas pessoas, e as pessoas podem torná-lo mais gentil. boa noite, pip. boa noite a todos.": ""});
